sites.find:
SpriteDepthNode* previous = 0;
SpriteDepthNode* cursor = head;
while (cursor != 0 && depth_key < cursor->depth_key) {
    previous = cursor;
    cursor = cursor->next;
}
if (cursor == 0) {
    previous->next = node;
    node->next = 0;
} else if (previous != 0) {
    previous->next = node;
    node->next = cursor;
} else {
    node->next = cursor;
    g_sprite_depth_buckets[bucket_index] = node;
}

